template <typename T>
struct Optional_Core_Impl {
    bool engaged_; // The engagement flag (often 1 byte)

    // Union ensures storage size is max(T, padding)
    union Storage {
        Storage() {} // Trivial constructor needed for union
        T value;     // Storage for the contained value
        char pad;    // Ensures union is non-empty/alignment
    } data;

    // Access methods rely on engaged_
    explicit operator bool() const { return engaged_; }
    T& operator*() { return data.value; }
};

// Size: sizeof(T) + sizeof(bool) + alignment padding
